/* Loudness trims — generated by tools/build-loudness.mjs.
 *
 * Every value is a gain in dB applied to the player's volume: negative means
 * "play this quieter". Values are measured with ffmpeg's EBU R128 scanner
 * against the median loudness of the local catalogue, so the world feed and the
 * studio songs land on the same level and the hourly handoff does not jump.
 *
 * Rebuild after adding music or refreshing the station list:
 *   node tools/build-loudness.mjs
 *
 * An empty table is a valid state: everything plays at the listener's volume.
 */
export const LOUDNESS = {
  target: null,
  tracks: {},
  stations: {}
};
